package br.com.onda;
import org.junit.Test;
import static org.junit.Assert.*;
public class AppearancePaletteTest {
 @Test public void allInterfacesKeepReadableTextAndAccent(){java.util.Set<String> ids=new java.util.HashSet<>();assertEquals(19,AppearancePalette.ALL.length);for(AppearancePalette p:AppearancePalette.ALL){assertTrue(ids.add(p.id));for(int background:new int[]{p.bg,p.end,p.surface,p.raised,AppearancePalette.blend(p.surface,p.accent,p.variant>0?.08f:.13f)}){assertTrue(p.name+" body contrast",AppearancePalette.contrast(AppearancePalette.TEXT,background)>=4.5);assertTrue(p.name+" secondary contrast",AppearancePalette.contrast(AppearancePalette.MUTED,background)>=4.5);}assertTrue(p.name+" accent",AppearancePalette.contrast(p.accent,p.surface)>=4.5);assertTrue(p.name+" primary button",AppearancePalette.contrast(p.bg,p.accent)>=4.5);}}
 @Test public void futuristicFacesAndEmblemsStayReadable(){java.util.Set<Integer> variants=new java.util.HashSet<>();for(AppearancePalette p:AppearancePalette.ALL)if(p.variant>0){assertTrue(p.variant>=1&&p.variant<=10);variants.add(p.variant);for(int fill:new int[]{p.surface,p.raised,AppearancePalette.blend(p.surface,p.accent,.08f),AppearancePalette.blend(p.surface,p.secondary,.08f)}){int top=AppearancePalette.blend(fill,0xFFFFFFFF,.04f);assertTrue(p.name+" bevel contrast",AppearancePalette.contrast(AppearancePalette.MUTED,top)>=4.5);}assertTrue(p.name+" recessed primary contrast",AppearancePalette.contrast(p.bg,AppearancePalette.blend(p.accent,p.bg,.36f))>=4.5);}assertEquals(10,variants.size());}
 @Test public void invalidOrMissingChoiceFallsBackToOriginal(){assertSame(AppearancePalette.ALL[0],AppearancePalette.find(null));assertSame(AppearancePalette.ALL[0],AppearancePalette.find("missing"));assertSame(AppearancePalette.ALL[1],AppearancePalette.find("nebula"));}
}
